fields.ValueConv:
ToFloat(@val);
return undef unless $val[0] and $val[1];
my $corr = 1;
if ($val[2]) {
    my $d = 1000 * $val[2] - $val[0];
    $corr += $val[0]/$d if $d > 0;
}
my $fd2 = atan2(36, 2*$val[0]*$val[1]*$corr);
my @fov = ( $fd2 * 360 / 3.14159 );
if ($val[2] and $val[2] > 0 and $val[2] < 10000) {
    push @fov, 2 * $val[2] * sin($fd2) / cos($fd2);
}
return join(' ', @fov);

