foreach (0,2) {
    next unless defined $val[$_] and IsFloat($val[$_]);
    next unless defined $prt[$_+1] and $prt[$_+1] =~ /Sea/;
    return((int($val[$_]*10)/10) . ' m ' . $prt[$_+1]);
}
$val = int($val * 10) / 10;
