fields.ValueConv:
my $time = $val[1];
my $diff = $val[2];
# handle time zone and shift to UTC
if ($time =~ s/([-+])(\d{1,2}):?(\d{2})$//) {
    my $secs = (($2 * 60) + $3) * 60;
    $secs *= -1 if $1 eq '+';
    $diff += $secs;
} elsif ($time !~ s/Z$//) {
    # shift from local time
    $diff += GetUnixTime($time, 1) - GetUnixTime($time);
}
my $sign = ($diff =~ s/^-// ? '-' : '');
$time .= '.000';    # add decimal seconds
ShiftTime($time, "${sign}0:0:$diff");
return $time . 'Z';

fields.RawConv:
return undef unless $val[1];
$val[1] /= $$self{TimeScale} if $$self{TimeScale};
my $key = 'MediaDataSize';
my $size = $val[0];
for (;;) {
