}
return((($val[0] and lc($val[0]) eq 'true') ? 0x01 : 0) |
       (($val[1] || 0) << 1) |
       (($val[2] || 0) << 3) |
       (($val[3] and lc($val[3]) eq 'true') ? 0x20 : 0) |
